import{z as s,x as n,o as r,c as d,q as l,j as A,D as E,d as t,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"NewSQL 谱系","description":"","frontmatter":{"title":"NewSQL 谱系","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dt-newsql-family.md","filePath":"cs/dt-newsql-family.md","lastUpdated":1791063341000}'),c={name:"cs/dt-newsql-family.md"};function p(T,a,D,m,C,S){const B=n("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="newsql-谱系" tabindex="-1">NewSQL 谱系 <a class="header-anchor" href="#newsql-谱系" aria-label="Permalink to &quot;NewSQL 谱系&quot;">​</a></h1><div class="epigraph"><p>NewSQL 不是一种协议，是提交时间戳的四个来源在产品里的分岔：真时钟区间、中心发号、混合逻辑钟、确定性日志。</p><footer>—— 据 Pavlo and Aslett, What&#39;s Really New with NewSQL?, SIGMOD Record 2016；本课程前三课的协议账</footer></div><p><a href="/cs/dt-calvin-deterministic">上一课</a>用日志序把提交对话整块免掉，加上此前的 2PC 日志序与 Percolator 主锁，协议课的账钉完了。主干课的 <a href="/cs/newsql">NewSQL</a> 给过「四问读系统」的清单；本课是谱系课，用这份清单给产品族排座次——各家真正分岔的位置只有一个：跨片事务的提交点与时间戳放在哪。后两课在这张谱系图上收束隔离与选型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「NewSQL」标的是承诺——SQL、强一致、自动分片——不是机制。缺口是<strong>把商标翻译回协议</strong>，不翻译就没法比较：CockroachDB 拿不到 Google 的原子钟，用混合逻辑钟近似 TrueTime，读碰到不确定区间就重启事务；TiDB 沿 Percolator 路线，把 TSO 放进 PD，SQL 层与 KV 层拆开部署；FaunaDB 一类沿 Calvin 路线；VoltDB 干脆按分区串行执行，跨分区事务让存储过程显式处理。延迟数字里的差距，很多时候不是工程优劣，是协议税不同——翻译不出协议，基准测试就没有可比性，选型就变成比谁的宣传页厚。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>谱系按三个轴读。轴一，提交时间戳从哪来：TrueTime 区间（Spanner，硬件合同）、TSO 中心发号（TiDB，多一跳 RPC、发号器要扩容）、HLC 混合逻辑钟（CockroachDB，无硬件依赖，不确定窗靠协议消化）、日志位置当序（Calvin 系，干脆取消时间戳）。轴二，锁住哪：组长内存（Spanner）、数据表（Percolator 系）、键序定序（Calvin 系）。轴三，部署形状：TiDB 是无状态 SQL 节点加 TiKV 加 PD 的三层；CockroachDB 是单一二进制，Range 为单位组 Raft，底层 LSM 引擎 Pebble。公约数也看得清：所有系统都用共识复制每个分片，2PC 只出现在跨分片提交点上——「共识管复制、2PC 管提交」的分工是全谱系的公约数，<a href="/cs/consensus-vs-2pc">共识与 2PC</a> 的口径在这里兑现成产品结构。</p><p><span class="marginnote">CockroachDB 的读不确定区间：读到的值其时间戳落在自己的不确定窗内，就整体重启事务换新时间戳——用重试代替原子钟；混合逻辑钟的文献锚点是 Kulkarni 等人 2014 年的 Logical Physical Clocks。</span></p><p><span class="marginnote">TSO（Timestamp Oracle）直译是「时间戳神谕」：全集群只有它一个发号器，任何事务要戳都得问它一趟。好处是戳绝对全局可比，坏处是它是中心依赖——所以运维清单里 TiDB 的 PD 要可扩容、可恢复：发号器一挂，全库写事务都得停摆。</span></p><p><span class="marginnote">HLC 可以类比「手表加排队叫号」：平时看物理钟走，一旦发现别的节点手里的号比自己大，就把自己的号推到比它大一点——逻辑部分专门兜住时钟不同步。代价是读到落在自己「不确定窗」内的数据时只能整个事务重来，CockroachDB 是拿重试次数换原子钟的钱。</span></p>',10)),(r(),A(i,null,{default:E(()=>[o(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E8%B7%A8%E5%88%86%E7%89%87%E4%BA%8B%E5%8A%A1%EF%BC%9A%E5%90%8C%E6%97%B6%E5%86%99%E5%88%86%E7%89%87%20A%20%E4%B8%8E%20B%22%5D%20--%3E%20PRE%5B%22prepare%20%E9%98%B6%E6%AE%B5%22%5D%0A%20%20PRE%20--%3E%20RAFTA%5B%22%E5%88%86%E7%89%87%20A%20%E7%9A%84%20Raft%20%E7%BB%84%EF%BC%9A%E5%A4%8D%E5%88%B6%E5%B9%B6%E7%A1%AE%E8%AE%A4%20prepare%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20PRE%20--%3E%20RAFTB%5B%22%E5%88%86%E7%89%87%20B%20%E7%9A%84%20Raft%20%E7%BB%84%EF%BC%9A%E5%A4%8D%E5%88%B6%E5%B9%B6%E7%A1%AE%E8%AE%A4%20prepare%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20RAFTA%20--%3E%20ALL%5B%22%E4%B8%A4%E7%BB%84%E9%83%BD%E7%A1%AE%E8%AE%A4%E8%90%BD%E7%9B%98%22%5D%0A%20%20RAFTB%20--%3E%20ALL%0A%20%20ALL%20--%3E%20P2%5B%222PC%20%E5%8D%8F%E8%B0%83%E8%80%85%EF%BC%9A%E5%86%B3%E5%AE%9A%E5%B9%B6%E5%AE%A3%E5%B8%83%E6%8F%90%E4%BA%A4%22%5D%0A%20%20P2%20--%3E%20CMT%5B%22commit%20%E6%A0%87%E8%AE%B0%E5%86%8D%E7%BB%8F%20Raft%20%E5%A4%8D%E5%88%B6%E5%88%B0%E5%90%84%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"为什么分岔点是时间戳：快照读要求全局可比的读时间，写提交要求全局可比的提交序——下一课要钉的「隔离 = 可比戳加提交点校验」，前一半正是它的产物。四种来源就是四种把「全局序」造出来的办法，各付各的税：TrueTime 付硬件与 commit wait；TSO 付一跳 RPC 与发号器可用性；HLC 付不确定窗与读重启；确定性付访问集预知与批处理延迟。看穿这一点，产品手册里「跨地域强一致」的宣传都能折算成四者之一再加一个距离税：跨地域的每次提交至少付一次广域往返，问题只是这笔钱付在哪一步、由谁看见。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"距离税代个数：光在光纤里每毫秒走约 200 公里，北京到美东单向就要 50 毫秒往上，一次广域往返轻松到 150 毫秒量级。Spanner 的 commit wait 约 7 毫秒看着不大，跨洲部署时真正的大头在往返距离上——这部分谁家的协议都免不掉。")],-1)),(r(),A(i,null,{default:E(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAM%5B%22NewSQL%20%E8%B0%B1%E7%B3%BB%22%5D%20--%3E%20TT%5B%22TrueTime%20%E5%8C%BA%E9%97%B4%EF%BC%9ASpanner%22%5D%0A%20%20FAM%20--%3E%20TSO%5B%22TSO%20%E5%8F%91%E5%8F%B7%EF%BC%9ATiDB%20%2F%20TiKV%22%5D%0A%20%20FAM%20--%3E%20HLC%5B%22HLC%20%E4%B8%8D%E7%A1%AE%E5%AE%9A%E7%AA%97%EF%BC%9ACockroachDB%22%5D%0A%20%20FAM%20--%3E%20DET%5B%22%E6%97%A5%E5%BF%97%E5%BA%8F%E5%BD%93%E5%BA%8F%EF%BC%9ACalvin%20%E7%B3%BB%22%5D%0A%20%20TT%20--%3E%20HW%5B%22%E7%A1%AC%E4%BB%B6%E6%97%B6%E9%92%9F%E5%90%88%E5%90%8C%20%2B%20commit%20wait%22%5D%0A%20%20TSO%20--%3E%20PERC%5B%22Percolator%20%E4%B8%BB%E9%94%81%22%5D%0A%20%20HLC%20--%3E%20RAFT%5B%22Range%20%E7%BA%A7%E5%85%B1%E8%AF%86%20%2B%202PC%22%5D%0A%20%20DET%20--%3E%20NOLK%5B%22%E5%85%8D%E9%94%81%E8%A1%A8%E4%B8%8E%E6%8F%90%E4%BA%A4%E5%AF%B9%E8%AF%9D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做产品排名，不展开分片中间件（Vitess 一类）的 XA 细节，也不把 Aurora 这类「存储服务化」硬塞进谱系——它的单写者模型把跨片提交问题整个绕开，是另一条路，口径归 <a href="/cs/storage-compute-separation">存算分离</a>。存储引擎内部 LSM 与 B+ 的账归存储课。下一课单独钉「隔离级别在分布式下怎么实现」：谱系里的四种时间戳来源，如何变成用户看得见的异常表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NewSQL 的承诺是 SQL 加强一致加分片；机制分岔在提交时间戳来源与锁的位置。</li><li>谱系四条：TrueTime 区间、TSO 发号、HLC 不确定窗、确定性日志，各付各的税。</li><li>公约数是「共识管复制、2PC 管跨片提交」；分歧是提交点放哪、时间税付在哪一步。</li><li>读白皮书先翻译协议再谈数字：延迟差距里含协议税，不全是工程优劣。</li><li>出处：Pavlo and Aslett, SIGMOD Record 2016；Corbett et al. 2012；Thomson et al. 2012；Kulkarni et al. 2014。</li></ul>',4))])}const u=s(c,[["render",p]]);export{P as __pageData,u as default};
